theorem exists_integrable_inverse_tail {f : ℂ → E}
    {p : FormalMultilinearSeries ℂ ℂ E} {N : ℕ}
    (hf : HasFPowerSeriesAt f p 0) (hp : ∀ k < N, p.coeff k = 0) (hN : 2 ≤ N) :
    ∃ R : ℝ, 1 ≤ R ∧
      ContinuousOn (fun r : ℝ => f ((r : ℂ)⁻¹)) (Ici R) ∧
      IntegrableOn (fun r : ℝ => f ((r : ℂ)⁻¹)) (Ici R)

theorem exists_inverse_tail_bound {f : ℂ → E}
    {p : FormalMultilinearSeries ℂ ℂ E} {N : ℕ}
    (hf : HasFPowerSeriesAt f p 0) (hp : ∀ k < N, p.coeff k = 0) :
    ∃ C : ℝ, 0 < C ∧ ∃ R : ℝ, 1 ≤ R ∧
      ContinuousOn (fun r : ℝ => f ((r : ℂ)⁻¹)) (Ici R) ∧
      ∀ r : ℝ, R ≤ r → ‖f ((r : ℂ)⁻¹)‖ ≤ C / r ^ N

theorem isBigO_of_initial_coefficients_zero {f : ℂ → E}
    {p : FormalMultilinearSeries ℂ ℂ E} {N : ℕ}
    (hf : HasFPowerSeriesAt f p 0) (hp : ∀ k < N, p.coeff k = 0) :
    f =O[𝓝 0] (fun z : ℂ => ‖z‖ ^ N)

theorem actualDefect_continuousAt {a : ℂ → Matrix ι ι ℂ} {z : ℂ}
    (ha : ContinuousAt a z) (P B : PowerSeries (Matrix ι ι ℂ)) (q N : ℕ) :
    ContinuousAt (actualDefect a P B q N) z

theorem gauge_hasDerivAt {b : ℝ → ℂ} {R r : ℝ}
    (hb : ContinuousOn b (Ici R)) (hr : R ≤ r) :
    HasDerivAt (gauge b R) (b r * gauge b R r) r

theorem primitive_hasDerivAt {b : ℝ → ℂ} {R r : ℝ}
    (hb : ContinuousOn b (Ici R)) (hr : R ≤ r) :
    HasDerivAt (primitive b R) (b r) r

theorem diagonal_mulVec_norm_le {m : ℕ} (d x : Fin m → ℂ) {B : ℝ}
    (hB : 0 ≤ B) (hd : ∀ i, ‖d i‖ ≤ B) :
    ‖(Matrix.diagonal d).mulVec x‖ ≤ B * ‖x‖

theorem eventually_original_pole_free {m : ℕ}
    (A : Matrix (Fin m) (Fin m) (RatFunc ℂ)) (θ : ℝ) :
    ∀ᶠ r : ℝ in atTop, ∀ i j, (A i j).denom.eval (ray θ r) ≠ 0

theorem det_fundamentalMatrix_ne_zero {m : ℕ} {a : ℝ}
    (u : Fin m → Ici a →ᵇ (Fin m → ℂ)) (Q : Fin m → ℝ → ℂ) {r : ℝ}
    (hu : (normalizedMatrix u r).det ≠ 0) : (fundamentalMatrix u Q r).det ≠ 0

theorem extend_tendsto {α : Type*} [TopologicalSpace α] {a : ℝ}
    {u : Ici a → α} {v : α} (hu : Tendsto u atTop (𝓝 v)) :
    Tendsto (extend a u) atTop (𝓝 v)

theorem eventually_det_ne_zero {α : Type*} {m : ℕ} {l : Filter α}
    {U : α → Matrix (Fin m) (Fin m) ℂ}
    (hU : Tendsto U l (𝓝 1)) :
    ∀ᶠ r in l, (U r).det ≠ 0

theorem eventually_inverse_identities {α : Type*} {m : ℕ} {l : Filter α}
    {U : α → Matrix (Fin m) (Fin m) ℂ}
    (hU : Tendsto U l (𝓝 1)) :
    ∀ᶠ r in l, (U r)⁻¹ * U r = 1 ∧ U r * (U r)⁻¹ = 1

theorem tendsto_inv_of_tendsto_one {α : Type*} {m : ℕ} {l : Filter α}
    {U : α → Matrix (Fin m) (Fin m) ℂ}
    (hU : Tendsto U l (𝓝 1)) :
    Tendsto (fun r => (U r)⁻¹) l (𝓝 1)

theorem matrix_product_hasDerivAt {m : ℕ}
    (H U : ℝ → Matrix (Fin m) (Fin m) ℂ)
    (H' U' : Matrix (Fin m) (Fin m) ℂ) {r : ℝ}
    (hH : ∀ i j, HasDerivAt (fun t => H t i j) (H' i j) r)
    (hU : ∀ i j, HasDerivAt (fun t => U t i j) (U' i j) r) (i j : Fin m) :
    HasDerivAt (fun t => (H t * U t) i j) ((H' * U r + H r * U') i j) r

theorem existsUnique_sylvester_of_nilpotent_parts {α β : ℂ}
    (hαβ : α ≠ β) {N : Matrix m m ℂ} {M : Matrix n n ℂ}
    (hN : IsNilpotent N) (hM : IsNilpotent M) (C : Matrix m n ℂ) :
    ∃! X : Matrix m n ℂ, (α • 1 + N) * X - X * (β • 1 + M) = C

theorem exists_block_coefficient {α β : ℂ} (hαβ : α ≠ β)
    {N : Matrix m m ℂ} {M : Matrix n n ℂ}
    (hN : IsNilpotent N) (hM : IsNilpotent M)
    (H : Matrix (m ⊕ n) (m ⊕ n) ℂ) :
    ∃ X : Matrix m n ℂ, ∃ Y : Matrix n m ℂ,
      let A₀ := Matrix.fromBlocks (α • 1 + N) 0 0 (β • 1 + M)
      let P := Matrix.fromBlocks 0 X Y 0
      let B := Matrix.fromBlocks (-H.toBlocks₁₁) 0 0 (-H.toBlocks₂₂)
      A₀ * P - P * A₀ = B + H

theorem isUnit_sylvester_of_nilpotent_parts {α β : ℂ}
    (hαβ : α ≠ β) {N : Matrix m m ℂ} {M : Matrix n n ℂ}
    (hN : IsNilpotent N) (hM : IsNilpotent M) :
    IsUnit (sylvester (α • 1 + N) (β • 1 + M))

theorem shift_mul_apply {h k : ℕ}
    (P : Matrix (Fin (h + 1)) (Fin k) ℂ) (i : Fin (h + 1)) (j : Fin k) :
    (shift h * P) i j = if hi : i.val < h then P ⟨i.val + 1, by omega⟩ j else 0

@[simp] theorem block_assemble {h : σ → ℕ}
    (P : ∀ a b, Matrix (Fin (h a + 1)) (Fin (h b + 1)) ℂ) (a b : σ) :
    block (assemble P) a b = P a b

theorem auxiliary_inverse {σ : Type*} [Fintype σ] [DecidableEq σ] (h : σ → ℕ) :
    let B := Matrix.blockDiagonal' (fun a => localB (h a))
    B⁻¹ * B = 1 ∧ B * B⁻¹ = 1

theorem afterColumns_bottom_right {h : σ → ℕ}
    (C : Matrix (OldIndex h) (OldIndex h) ℂ) (a b : σ) :
    afterColumns C (.inr a) (.inr b) = presentation C a b

theorem afterColumns_top_right {h : σ → ℕ} {C : Matrix (OldIndex h) (OldIndex h) ℂ}
    (hC : LastRowForm h C) (a b : σ) (i : Fin (h a)) :
    afterColumns C (.inl ⟨a, i⟩) (.inr b) = 0

theorem pencil_mulVec_top {h : σ → ℕ} {C : Matrix (OldIndex h) (OldIndex h) ℂ}
    (hC : LastRowForm h C) (v : OldIndex h → ℂ[X]) (a : σ) (i : Fin (h a)) :
    (pencil C *ᵥ v) ⟨a, i.castSucc⟩ = X * v ⟨a, i.castSucc⟩ - v ⟨a, i.succ⟩

theorem pencil_degreeMass_le {s : ℕ} {h : Fin s → ℕ}
    {C : Matrix (OldIndex h) (OldIndex h) ℂ}
    (hC : LastRowForm h C) (hL : LowerBlocks h C) (hD : ShiftDiagonal h C) :
    degreeMass (pencil C) ≤ degreeMass (pencil (WasowMultiShiftReduction.jordanShift h))

theorem pencil_degreeMass_strict_drop {s : ℕ} {h : Fin s → ℕ}
    {C : Matrix (OldIndex h) (OldIndex h) ℂ}
    (hh : Monotone h) (hC : LastRowForm h C) (hL : LowerBlocks h C) (hD : ShiftDiagonal h C)
    (hn : ∃ a b, a ≠ b ∧ ∃ j, C ⟨a, Fin.last (h a)⟩ ⟨b, j⟩ ≠ 0) :
    degreeMass (pencil C) < degreeMass (pencil (WasowMultiShiftReduction.jordanShift h))

theorem presentation_diag {s : ℕ} {h : Fin s → ℕ}
    {C : Matrix (OldIndex h) (OldIndex h) ℂ} (hD : ShiftDiagonal h C) (a : Fin s) :
    presentation C a a = X ^ (h a+1)

theorem presentation_lower {s : ℕ} {h : Fin s → ℕ}
    {C : Matrix (OldIndex h) (OldIndex h) ℂ} (hL : LowerBlocks h C) :
    (presentation C).IsLowerTriangular

theorem krylovRows_det_one {h : ℕ}
    (N : Matrix (Fin (h+1)) (Fin (h+1)) ℂ) (α : ℂ) (hrows : ShiftRows N α) :
    (krylovRows N).det = 1

theorem krylovRows_intertwines {h : ℕ}
    (N : Matrix (Fin (h+1)) (Fin (h+1)) ℂ) (hN : IsNilpotent N) :
    krylovRows N * N = WasowShiftReduction.shift h * krylovRows N

theorem krylovRows_last_column {h : ℕ}
    (N : Matrix (Fin (h+1)) (Fin (h+1)) ℂ) (α : ℂ) (hrows : ShiftRows N α)
    (i : Fin (h+1)) : krylovRows N i (Fin.last h) = if i=Fin.last h then 1 else 0

theorem diagonalBlock_mul {h : σ → ℕ}
    (C D : Matrix (Index h) (Index h) ℂ) (hC : LowerBlocks C) (hD : LowerBlocks D)
    (a : σ) : block (C*D) a a = block C a a * block D a a

theorem diagonalBlock_nilpotent {h : σ → ℕ}
    (C : Matrix (Index h) (Index h) ℂ) (hC : LowerBlocks C)
    (hN : IsNilpotent C) (a : σ) : IsNilpotent (block C a a)

theorem diagonalBlock_pow {h : σ → ℕ}
    (C : Matrix (Index h) (Index h) ℂ) (hC : LowerBlocks C) (a : σ) (k : ℕ) :
    block (C^k) a a = (block C a a)^k

theorem diagonalBlock_sub_scalar {h : σ → ℕ}
    (C : Matrix (Index h) (Index h) ℂ) (α : ℂ) (a : σ) :
    block (C-α • 1) a a = block C a a - α • 1

theorem lastRowForm_diagonal_rows {h : σ → ℕ}
    (C : Matrix (Index h) (Index h) ℂ) (hC : LastRowForm h C) (a : σ) :
    ∀ i j, i.val < h a → block C a a i j = if j.val=i.val+1 then 1 else 0

theorem lastRowForm_offDiagonal_rows {h : σ → ℕ}
    (C : Matrix (Index h) (Index h) ℂ) (hC : LastRowForm h C)
    (a b : σ) (hab : a≠b) : ∀ i j, i.val < h a → block C a b i j=0

theorem lowerBlocks_sub_scalar {h : σ → ℕ}
    (C : Matrix (Index h) (Index h) ℂ) (hC : LowerBlocks C) (α : ℂ) :
    LowerBlocks (C-α • 1)

theorem offDiagonalBlock_sub_scalar {h : σ → ℕ}
    (C : Matrix (Index h) (Index h) ℂ) (α : ℂ) (a b : σ) (hab : a≠b) :
    block (C-α • 1) a b = block C a b

theorem positiveBasis_zero (f : End ℂ V) {d : ℕ} {k : Fin d → ℕ}
    (e : Module.AEval' f ≃ₗ[ℂ[X]] ⨁ a : Fin d, Truncated (k a))
    (a : {a : Fin d // 0 < k a}) : f (positiveBasis f e ⟨a, 0⟩) = 0

theorem eventually_value_matrix_mul {m : ℕ}
    (A B : Matrix (Fin m) (Fin m) (RatFunc ℂ)) (θ : ℝ) :
    ∀ᶠ r in atTop, (A * B).map (value θ r) = A.map (value θ r) * B.map (value θ r)

theorem clearedDefect_continuousAt (a h N : ℕ) {c : ℂ → Matrix ι ι ℂ}
    {z : ℂ} (hc : ContinuousAt c z) (P B : Series (ι := ι)) :
    ContinuousAt (WasowClearedResidual.actualDefect a h N c P B) z

theorem numerator_degree_le_order {m : ℕ}
    (A : Matrix (Fin m) (Fin m) (RatFunc ℂ)) (i j : Fin m) :
    (A i j).num.natDegree ≤ order A

theorem rayAnalytic_analytic {m : ℕ}
    (A : Matrix (Fin m) (Fin m) (RatFunc ℂ)) (θ : ℝ) :
    AnalyticAt ℂ (rayAnalytic A θ) 0

theorem hasFPowerSeriesAt_rotate {a : ℂ → Matrix ι ι ℂ}
    {s : FormalMultilinearSeries ℂ ℂ (Matrix ι ι ℂ)}
    (ha : HasFPowerSeriesAt a s 0) (u : ℂ) (d : ℕ) :
    HasFPowerSeriesAt (rotateAnalytic u d a) (rotateTaylor u d s) 0
